import React from "react";
import Slider from "react-slick";

export default function Hero() {
  const settings = {
    dots: true,
    infinite: true,
    speed: 150, // Faster transition speed
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000, // Faster sliding interval
  };

  const slides = [
    { src: "/welcomingPoster.png", alt: "Image 1" },
    { src: "/poster1.png", alt: "Image 2" },
    { src: "/poster2.png", alt: "Image 3" },
  ];

  return (
    <section
      className="relative overflow-hidden mt-12 mb-8 px-4 sm:px-6 lg:px-8"
    >
      <div className="h-[200px] sm:h-[300px] md:h-[400px] lg:h-[500px]">
        <Slider {...settings}>
          {slides.map((slide, index) => (
            <div key={index} className="relative h-[200px] sm:h-[300px] md:h-[400px] lg:h-[500px]">
              <img
                src={slide.src}
                alt={slide.alt}
                className="w-full h-full object-contain"
              />
            </div>
          ))}
        </Slider>
      </div>
    </section>
  );
}
